{
  "apiVersion": 1,
  "type": "help",
  "data": {
    "command": "astryx gap-report",
    "description": "Report a missing component or feature to the package that owns it",
    "usage": "astryx gap-report [options] [component]",
    "options": [
      {
        "flags": "--category <category>",
        "description": "Gap category (run --list-categories for values). Required unless --list-categories is set."
      },
      {
        "flags": "--reason <reason>",
        "description": "What capability was missing or difficult, up to 2000 characters. Required unless --list-categories is set."
      },
      {
        "flags": "--additional-context <text>",
        "description": "Optional additional context, up to 8000 characters"
      },
      {
        "flags": "--package <pkg>",
        "description": "Package that owns the gap: @astryxdesign/core or a loaded integration. Overrides automatic routing, which picks the integration whose component replaces the named Core component, else the one package that provides it, else Core; needed when more than one package provides the component"
      },
      {
        "flags": "--confirm-public",
        "description": "Allow public delivery: public handlers run, and a GitHub issues URL gets an issue filed with your gh login"
      },
      {
        "flags": "--to <package>",
        "description": "Send the report only to this loaded integration's issues URL, as the person chose; the destinations the output lists are the choices"
      },
      {
        "flags": "--list-categories",
        "description": "List valid report categories, and the destinations when there is more than one, without filing; the component and the other gap-report options are refused with ERR_INVALID_ARGUMENT"
      }
    ],
    "subcommands": []
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
